# -*- coding: utf-8 -*-
"""recomp: ROM -> lifted x86_64 (GAS) + C driver artifacts.

Usage:  python -m recomp.recomp <file.nes> <outdir>   (run from nes/src)
Writes: outdir/generated.s, gen_blocks.h, main.c, build.bat
"""
import os
import shutil
import sys

from .ines import Cartridge
from .decoder import decode_program, decode_reachable, build_blocks
from .codegen import Codegen


def gen_blocks_header(blocks, entry):
    out = [
        "/* generated by recomp.py — do not edit */",
        "#ifndef GEN_BLOCKS_H",
        "#define GEN_BLOCKS_H",
        "",
        "typedef struct { unsigned int start_pc; unsigned short cycles;",
        " unsigned char is_ppu_io; unsigned char rw; unsigned short addr; } BlockInfo;",
        "",
    ]
    from . import ops
    ents = []
    for i, blk in enumerate(blocks):
        first = blk["instrs"][0]
        kind = ops.io_kind(first.mn, first.mode, first.operand)
        is_io = 1 if kind else 0
        rw = 0 if first.mn == "LDA" else 1
        addr = first.operand if kind else 0
        ents.append("  { 0x%04X, %d, %d, %d, 0x%04X }  /* b%d: %d instrs */" % (
            blk["start"], blk["cycles"], is_io, rw, addr, i, len(blk["instrs"])))
    out.append(f"#define N_BLOCKS {len(blocks)}")
    out.append("static const BlockInfo g_blocks[N_BLOCKS] = {")
    out.append(",\n".join(ents))
    out.append("};")
    out += [f"extern void rt_b{i}(void);" for i in range(len(blocks))]
    out.append("static const void *const g_entries[N_BLOCKS] = {")
    out.append("  " + ", ".join(f"(const void*)&rt_b{i}" for i in range(len(blocks))) + "  ")
    out.append("};")
    out.append(f"#define ENTRY_PC 0x{entry:04X}")
    out += ["", "#endif", ""]
    return "\n".join(out)


MAIN_C = r"""/* generated driver — runs the lifted program for LIMIT cpu cycles */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "runtime.h"
#include "gen_blocks.h"

static unsigned short block_index[0x10000];

int main(int argc, char **argv) {
    /* default: one full NTSC frame of CPU (29,780 cycles @ 3:1) */
    unsigned long long limit = (argc > 1) ? strtoull(argv[1], 0, 0)
                                          : (PPU_FRAME / PPU_PER_CPU);
    memset(rt_ram, 0, sizeof rt_ram);
    /* load PRG into the RAM image: caller passes it via rom_prg.bin if present */
    FILE *f = fopen("rom_prg.bin", "rb");
    if (f) { fseek(f, 0, SEEK_END); long n = ftell(f); fseek(f, 0, SEEK_SET);
             fread(rt_ram + 0x8000, 1, n, f); fclose(f);
             long m = n > 0x8000 ? 0x8000 : n;   /* mapper 0: $6000-$7FFF mirror PRG
                                                      (vectors at $7FFA-$7FFF live here) */
             memcpy(rt_ram + 0x6000, rt_ram + 0x8000, m); }
    memset(block_index, 0xFF, sizeof block_index);
    for (int i = 0; i < N_BLOCKS; i++)
        block_index[g_blocks[i].start_pc] = (unsigned short)i;
    for (unsigned a = 0; a < 0x10000; a++)
        rt_jmp[a] = (block_index[a] != 0xFFFF) ? g_entries[block_index[a]]
                                               : (void *)rt_jmp_invalid;

    /* 6502 reset: PC = vector; S = 0xFF; P = B|1 (bit5 hardwired 1). The
     * test driver keeps A/X/Y = 0; real reset values are unknown. */
    rt_cpu.a = 0; rt_cpu.x = 0; rt_cpu.y = 0;
    rt_cpu.s = 0xFD; rt_cpu.p = 0x30; rt_cpu.pc = ENTRY_PC; rt_cpu.nmi = 0;
    rt_ppu.pos = 0;

    unsigned long long next_nmi = NMI_POS;
    unsigned long long cpu = 0;
    unsigned long long nmi_taken = 0;
    while (cpu < limit) {
        if (rt_ppu.pos >= next_nmi) {           /* NMI at the block boundary */
            rt_ppu.pos = next_nmi;
            next_nmi += PPU_FRAME;
            rt_nmi_entry();                     /* pushes, pc = NMI vec */
            cpu += 7;                           /* NMI entry (7 cyc); the first handler
                                                   block is dispatched + credited by the
                                                   normal loop on the next iteration */
            rt_ppu.pos += 7 * PPU_PER_CPU;
            rt_extra = 0;
            nmi_taken++;
            continue;
        }
        unsigned short bi = block_index[rt_cpu.pc];
        if (bi == 0xFFFF) rt_halt();
        const BlockInfo *b = &g_blocks[bi];
        if (b->is_ppu_io) {
            if (b->rw) rt_ppu_write(b->addr, rt_cpu.a);
            else rt_cpu.a = rt_ppu_read(b->addr);
        }
        ((void (*)(void))g_entries[bi])();      /* block runs and RETURNS here */
        cpu += b->cycles + rt_extra;            /* rt_extra: branch-taken +1,
                                                   zp-X RMW page-cross +1 */
        rt_ppu.pos += (unsigned long long)(b->cycles + rt_extra) * PPU_PER_CPU;
        rt_extra = 0;
        if (rt_cpu.nmi) {                        /* in-block pending (rare) */
            rt_cpu.nmi = 0;
            rt_nmi_entry();
            cpu += 7;
            rt_ppu.pos += 7 * PPU_PER_CPU;
            rt_extra = 0;
            nmi_taken++;
        }
    }
    printf("RESULT cpu=%llu nmi=%llu a=%02X x=%02X y=%02X s=%02X p=%02X pc=%04X\n",
           cpu, nmi_taken, rt_cpu.a, rt_cpu.x, rt_cpu.y, rt_cpu.s,
           rt_cpu.p, rt_cpu.pc);
    /* fingerprint: a fixed, diff-able memory + PPU state slice */
    unsigned int addrs[] = {0x00,0x01,0x02,0x03,0x04,0x05,0x06,0x07,0x08,
                            0x0E,0x0F,0x14,0x17,0x18,0x19,0x200,0x201,0x320,0x430,0x9FFC};
    printf("MEM ");
    for (size_t i = 0; i < sizeof addrs / sizeof *addrs; i++)
        printf("$%03X=%02X ", addrs[i], rt_ram[addrs[i]]);
    printf("\nPPU puctl=%02X pumask=%02X oamaddr=%02X ptr=%02X oam=%02X %02X %02X %02X pos=%llu\n",
           rt_ppu.puctl, rt_ppu.pumask, rt_ppu.oamaddr, rt_ppu.ptr,
           rt_ppu.oam[0], rt_ppu.oam[1], rt_ppu.oam[2], rt_ppu.oam[3],
           rt_ppu.pos % PPU_FRAME);
    return 0;
}
"""


BATCH = r"""@echo off
rem build the lifted test program (run from the out/ dir)
set TC=C:\Users\peima\.local\share\retcomm\toolchains\cmake-clang-v1\latest\bin
"%TC%\x86_64-w64-mingw32-as.exe" -c generated.s -o generated.o || exit /b 1
"%TC%\x86_64-w64-mingw32-gcc.exe" main.c runtime.c ppu.c generated.o -o test.exe || exit /b 1
echo built test.exe
"""


def main():
    if len(sys.argv) != 3:
        print(__doc__)
        return 1
    rom_path, outdir = sys.argv[1], sys.argv[2]
    os.makedirs(outdir, exist_ok=True)

    car = Cartridge(rom_path)
    print("[recomp]", car.summary())
    nmi, reset, irq = car.vectors()
    ram = bytearray(car.rag_image()) if hasattr(car, "rag_image") else bytearray(car.ram_image())
    with open(os.path.join(outdir, "rom_prg.bin"), "wb") as f:
        f.write(ram[0x8000:])

    nmi_vec, reset_vec, irq_vec = car.vectors()
    seeds = [reset_vec]
    for v in (nmi_vec, irq_vec):
        if 0x8000 <= v < 0xFFFA and v not in seeds:
            seeds.append(v)
    instrs, starts = decode_reachable(ram, seeds)
    blocks = build_blocks(instrs, starts=starts)
    print(f"[recomp] {len(instrs)} instructions -> {len(blocks)} blocks "
          f"(seeds: {', '.join(hex(s) for s in sorted(seeds))})")

    cg = Codegen(ram, blocks)
    asm = cg.build()
    with open(os.path.join(outdir, "generated.s"), "w", newline="\n") as f:
        f.write(asm)
    with open(os.path.join(outdir, "gen_blocks.h"), "w") as f:
        f.write(gen_blocks_header(blocks, reset))
    with open(os.path.join(outdir, "main.c"), "w") as f:
        f.write(MAIN_C)
    # runtime C sources live in nes/src/runtime/ — copy into outdir so the
    # build dir is self-contained
    rtdir = os.path.normpath(os.path.join(os.path.dirname(__file__), "..", "runtime"))
    for name in ("runtime.c", "ppu.c", "runtime.h"):
        shutil.copy(os.path.join(rtdir, name), os.path.join(outdir, name))
    with open(os.path.join(outdir, "build.bat"), "w") as f:
        f.write(BATCH)
    print(f"[recomp] wrote generated.s ({len(asm.splitlines())} lines), gen_blocks.h, main.c, build.bat")
    return 0


if __name__ == "__main__":
    sys.exit(main())
